3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Canonicalizes the create-owner telephone to E.164 form, rejecting anything that cannot
9	 * form a valid E.164 number with a 400 via {@link InvalidTelephoneException}. Mutates the
10	 * published body in place so later steps (and the response) see the E.164 value.
11	 */
12	public class NormalizeOwnerTelephone {
13	
14	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
15	        String telephone = request.getTelephone();
16	        String e164 = OwnerTelephones.toE164(telephone);
17	        if (e164 == null) {
18	            throw new InvalidTelephoneException(telephone);
19	        }
20	        request.setTelephone(e164);
21	    }
22	}
