17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
22	    @Mapping(target = "initials", expression = "java(initials(owner))")
23	    OwnerDto toOwnerDto(Owner owner);
24	
25	    /** Format the stored names as 'LastName, FirstName'. */
26	    default String displayName(Owner owner) {
27	        if (owner == null) {
28	            return null;
29	        }
30	        return owner.getLastName() + ", " + owner.getFirstName();
31	    }
32	
33	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot (e.g. 'J.S.'). */
34	    default String initials(Owner owner) {
35	        if (owner == null) {
36	            return null;
37	        }
38	        return initial(owner.getFirstName()) + initial(owner.getLastName());
39	    }
40	
41	    private static String initial(String name) {
42	        if (name == null || name.isEmpty()) {
43	            return "";
44	        }
45	        return Character.toUpperCase(name.charAt(0)) + ".";
46	    }
47	
48	    Owner toOwner(OwnerDto ownerDto);
49	
50	    @Mapping(target = "id", ignore = true)
51	    @Mapping(target = "pets", ignore = true)
52	    Owner toOwner(OwnerFieldsDto ownerDto);
53	
54	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
55	
56	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
57	
58	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
59	        OwnerPageDto ownerPageDto = new OwnerPageDto();
60	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
61	        ownerPageDto.setPage(ownerPage.getNumber());
62	        ownerPageDto.setSize(ownerPage.getSize());
63	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
64	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
65	        return ownerPageDto;
66	    }
67	}
